## 3️⃣ Concrete Code Improvements

Below is a **drop‑in replacement** (`app.js`) that addresses the items above while preserving the original functionality.

```js
/**
 * Secure Express Application
 * -------------------------------------------------
 * Primary goals:
 *  • Harden defaults (Helmet, CORS, Rate‑limit)
 *  • Disable framework fingerprinting
 *  • Centralised error handling (no stack traces in prod)
 *  • Add a simple JWT‑based auth example (easily replaceable)
 */

require('dotenv').config();               // Load .env for config (port, secret, etc.)

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');      // <-- optional, just for example
const { body, validationResult } = require('express-validator');

const app = express();

// -------------------------------------------------
// 1️⃣  Global Middleware – secure defaults
// -------------------------------------------------
app.use(helmet());                         // Security headers (CSP, HSTS, etc.)
app.use(cors({
  origin: process.env.CORS_ORIGIN || '*', // Adjust for production
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
}));
app.disable('x-powered-by');               // Hide Express version

// Body parser with size limit – protects against DoS payloads
app.use(express.json({ limit: '1mb' }));

// HTTP request logging – production can switch to a file/remote logger
if (process.env.NODE_ENV !== 'test') {
  app.use(morgan('combined'));
}

// -------------------------------------------------
// 2️⃣  Rate limiting – mitigate brute‑force / DoS
// -------------------------------------------------
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                 // max 100 requests per IP per window
  standardHeaders: true,
  legacyHeaders: false,
});
app.use('/users', apiLimiter);   // Apply to endpoints that may become sensitive

// -------------------------------------------------
// 3️⃣  Simple JWT authentication middleware (example)
// -------------------------------------------------
const authRequired = (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed token' });
  }

  const token = authHeader.split(' ')[1];
  try {
    // `JWT_SECRET` must be a strong, random secret stored in env
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};

// -------------------------------------------------
// 4️⃣  Routes (still static, but now protected)
// -------------------------------------------------
app.get('/health', (req, res) => {
  // No sensitive data – safe to expose
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * Example: GET /users – only accessible with a valid JWT.
 * In a real service you would pull data from a DB using parameterised queries.
 */
app.get('/users', authRequired, (req, res) => {
  // Static list kept for demo; replace with DB call after validation/parameterisation.
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// -------------------------------------------------
// 5️⃣  Global error handler – hide stack traces in prod
// -------------------------------------------------
app.use((err, _req, res, _next) => {
  // Log the full error for operations team
  console.error(err);

  // Send generic message to client (avoid leak)
  const response = {
    error: 'Internal server error',
  };
  if (process.env.NODE_ENV !== 'production') {
    // In non‑production we can expose the message for debugging
    response.details = err.message;
  }
  res.status(err.status || 500).json(response);
});

// -------------------------------------------------
// 6️⃣  Server start – use env vars, graceful shutdown
// -------------------------------------------------
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// Graceful shutdown (important for containers / cloud environments)
function shutdown() {
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

module.exports = app;
```

### Highlights of the Patch

| Area | What changed & why |
|------|--------------------|
| **Config** | `dotenv` + `process.env` – never hard‑code secrets or ports. |
| **Headers** | `helmet()` adds CSP, X‑Frame‑Options, HSTS, etc.; `app.disable('x-powered-by')` removes framework fingerprint. |
| **CORS** | Configurable origin; restrict in production. |
| **Body parsing** | Size limit (`1mb`) prevents large payload attacks. |
| **Logging** | `morgan` logs requests; in production you should pipe to a log‑aggregator (e.g., Logfire, Elastic). |
| **Rate limiting** | Throttles abusive IPs. |
| **Auth** | Sample JWT guard demonstrates *A01* & *A07* mitigation. Replace with your own scheme (OAuth2, session cookies, etc.). |
| **Error handling** | Centralised handler that never returns stack traces in production (addresses *A05* and *A09*). |
| **Graceful shutdown** | Helps avoid sudden termination that could expose half‑finished responses or corrupt resources. |
| **Future‑proof** | Comments remind developers to use **parameterised queries** and **input validation** when they add data‑store calls. |

