## 3️⃣ Recommended Remediations (with **ready‑to‑copy code**)

### 3.1 Add a security‑middleware stack

```js
// --- security.js ----------------------------------------------------
const helmet = require('helmet');            // Sets secure HTTP headers
const cors   = require('cors');              // Controls cross‑origin access
const rateLimit = require('express-rate-limit');
const xssClean  = require('xss-clean');      // Basic XSS sanitisation
const hpp       = require('hpp');            // HTTP Parameter Pollution protection

module.exports = function (app) {
  // 1️⃣ Helmet – adds 12+ security headers (CSP, HSTS, etc.)
  app.use(helmet());

  // 2️⃣ CORS – only allow trusted origins (adjust list as needed)
  const whitelist = ['https://myapp.example.com'];
  const corsOptions = {
    origin: function (origin, callback) {
      if (!origin || whitelist.includes(origin)) {
        callback(null, true);
      } else {
        callback(new Error('Not allowed by CORS'));
      }
    },
    credentials: true,
  };
  app.use(cors(corsOptions));

  // 3️⃣ Rate limiting – mitigate brute‑force / DoS
  const apiLimiter = rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100,                 // limit each IP to 100 requests per window
    message: { error: 'Too many requests, try again later.' },
    standardHeaders: true,
    legacyHeaders: false,
  });
  app.use('/users', apiLimiter); // apply only to sensitive routes, or app.use(apiLimiter) for all

  // 4️⃣ Body‑parser size limits (if you ever add POST/PUT routes)
  app.use(express.json({ limit: '1kb' })); // adjust according to needs

  // 5️⃣ XSS & HPP protection
  app.use(xssClean());
  app.use(hpp());
};
```

