// auth.js – very lightweight JWT example (replace with your auth provider)
const jwt = require('jsonwebtoken');
const secret = process.env.JWT_SECRET || 'change‑me‑now';

function authenticate(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader) return res.status(401).json({ error: 'Missing Authorization header' });

  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, secret);
    req.user = payload; // attach user info for later RBAC checks
    next();
  } catch (e) {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
}

// RBAC helper – only admins may see the full user list
