const { query, validationResult } = require('express-validator');

app.get('/search',
  // 1️⃣ Validation rules
  [
    query('q')
      .trim()
      .isLength({ min: 3, max: 50 })
      .withMessage('Search term must be 3‑50 characters')
      .escape(),
    query('page')
      .optional()
      .isInt({ min: 1 })
