## Recommended Refactor: Load Secrets from a Secrets Manager

Below are three practical patterns you can adopt, depending on your cloud provider. Choose the one that matches your environment; the code snippets are intentionally minimal so you can drop them into `app.js` (or a dedicated `config.js`) with a few `npm i` commands.

### 1️⃣ AWS Secrets Manager (Node.js)

```bash
npm i @aws-sdk/client-secrets-manager
```

```js
// config/awsSecrets.js
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });

/**
 * Retrieves a secret (JSON string) from Secrets Manager.
 * @param {string} secretName - The name/ARN of the secret.
 * @returns {Promise<Object>} parsed JSON secret object.
 */
async function getSecret(secretName) {
  const cmd = new GetSecretValueCommand({ SecretId: secretName });
  const response = await client.send(cmd);
  const secretString = response.SecretString || Buffer.from(response.SecretBinary, 'base64').toString('utf-8');
  return JSON.parse(secretString);
}

module.exports = { getSecret };
```

Usage in `app.js` (async start‑up wrapper):

```js
const { getSecret } = require('./config/awsSecrets');

(async () => {
  try {
    const secret = await getSecret('myApp/prod/jwt'); // expects {"JWT_SECRET":"<value>"}
    process.env.JWT_SECRET = secret.JWT_SECRET;       // expose to the rest of the app

    // Optional: load other secrets (CORS list, DB credentials, etc.)
    const other = await getSecret('myApp/prod/config');
    process.env.CORS_ORIGIN = other.CORS_ORIGIN; // e.g. "https://myapp.example.com"
    // …continue to start the server after secrets are loaded
    require('./app'); // <-- the original Express app
  } catch (e) {
    console.error('❌ Unable to fetch secrets from AWS Secrets Manager:', e);
    process.exit(1);
  }
})();
```

**Benefits**

* Secrets are stored encrypted at rest and accessed via IAM policies, giving fine‑grained control.
* Rotation can be done in the console; the next app start picks up the new value automatically.
* No `.env` file needed in the container/host.

