```js
/**
 * Secure version of the demo Express app.
 *   • Adds security‑hardening middleware (helmet, cors, rate‑limit)
 *   • Implements a very simple token‑based auth for the /users endpoint
 *   • Uses dotenv for configuration, enables trust‑proxy, and forces HTTPS
 *   • Provides a global error‑handler + request logging (morgan)
 *   • Shows how to plug in future input validation with express‑validator
 */

require('dotenv').config();               // <‑‑ load .env (PORT, AUTH_TOKEN, etc.)

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');         // request logging
const { body, param, query, validationResult } = require('express-validator');

const app = express();

// ---------------------------------------------------------------------------
// 1️⃣ General security hardening
// ---------------------------------------------------------------------------
app.use(helmet());

// Restrict CORS to known origins only (change the array for production)
const allowedOrigins = process.env.CORS_ORIGINS?.split(',') ?? [];
app.use(
  cors({
    origin: (origin, callback) => {
      // allow non‑browser requests (e.g. health checks) with no origin
      if (!origin) return callback(null, true);
      if (allowedOrigins.includes(origin)) return callback(null, true);
      callback(new Error('Not allowed by CORS'));
    },
    methods: ['GET'],
    credentials: true,
  })
);

// Basic rate limiting – 100 requests per 15‑minute window per IP
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Enable trust‑proxy when running behind Nginx/HAProxy etc. (required for
// correct detection of secure connections and client IP)
app.enable('trust proxy');

// ---------------------------------------------------------------------------
// 2️⃣ Request parsing & logging
// ---------------------------------------------------------------------------
app.use(express.json()); // future POST/PUT bodies
app.use(morgan('combined')); // logs to stdout – replace with winston for production

// ---------------------------------------------------------------------------
// 3️⃣ Simple token‑based authentication middleware
// ---------------------------------------------------------------------------
const AUTH_TOKEN = process.env.AUTH_TOKEN || 'dev‑only‑replace‑me';

function requireAuth(req, res, next) {
  const token = req.headers.authorization?.replace(/^Bearer\s+/i, '');
  if (token && token === AUTH_TOKEN) {
    return next();
  }
  // generic message to avoid leaking info
  return res.status(401).json({ error: 'Unauthorized' });
}

// ---------------------------------------------------------------------------
// 4️⃣ Routes
// ---------------------------------------------------------------------------

// Health‑check – no auth, minimal info
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * Example of future input validation (currently none needed).
 * If you ever add query parameters like ?page=2 you could do:
 *
 * app.get(
 *   '/users',
 *   requireAuth,
 *   query('page').optional().isInt({ min: 1 }).toInt(),
 *   (req, res, next) => {
 *     const errors = validationResult(req);
 *     if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });
 *     …
 *   }
 * );
 */
app.get('/users', requireAuth, (req, res) => {
  // In a real app this would be fetched from a DB with proper RBAC.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json(users);
});

// ---------------------------------------------------------------------------
// 5️⃣ Global error handler (must be after all routes)
// ---------------------------------------------------------------------------
app.use((err, req, res, next) => {
  // Log the full stack trace only in development
  if (process.env.NODE_ENV !== 'production') {
    console.error(err);
  } else {
    // In prod you might forward to a log aggregation service instead
    // Example: logger.error(err);
  }

  const status = err.status || 500;
  const message = status === 500 ? 'Internal Server Error' : err.message;
  res.status(status).json({ error: message });
});

// ---------------------------------------------------------------------------
// 6️⃣ Server start (use env var, fall back to 3000)
// ---------------------------------------------------------------------------
const PORT = process.env.PORT || 3000;

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app;   // kept for unit‑tests
```

