## Recommended pattern – **pull secrets from a dedicated secrets manager**  

Below is a small, **framework‑agnostic** reference implementation that you can drop into `app.js` (or a separate `config.js` module).  It demonstrates **AWS Secrets Manager**, **Google Secret Manager**, and **HashiCorp Vault** – you can keep only the provider you use.

> 👉 **If you are happy with "environment variables only", you can skip the secret‑manager code and just make sure the values are injected by your orchestration platform.  The important part is **not** to ship a static `.env` file containing real secrets.**

```js
// config.js --------------------------------------------------------------
/**
 * Centralised configuration loader.
 *  • Tries to read from process.env first (the safest production pattern).
 *  • If a variable is missing and the app is running in a non‑production
 *    environment, fall back to a local .env file (developer convenience).
 *  • Provides optional helpers for AWS Secrets Manager, GCP Secret Manager,
 *    or HashiCorp Vault – you can enable any of them via the
 *    SECRET_PROVIDER env‑var.
 */

require('dotenv').config(); // loads .env only if it exists; safe for dev only

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');
const Vault = require('node-vault');

const env = process.env;

/**
 * Generic getter – returns the value from process.env or throws if missing.
 * Allows us to keep a single source of truth.
 */
function getRequired(name) {
  const val = env[name];
  if (!val) {
    throw new Error(`Configuration error – missing required env var ${name}`);
  }
  return val;
}

/**
 * Optional secret‑manager fetcher.
 *   SECRET_PROVIDER = 'aws' | 'gcp' | 'vault' | '' (empty = disabled)
 *   SECRET_NAME     = name identifier in the chosen store
 */
async function loadSecretFromProvider() {
  const provider = env.SECRET_PROVIDER?.toLowerCase();
  const secretId = env.SECRET_NAME; // e.g. "myapp/prod/db"

  if (!provider || !secretId) return; // nothing to do

  switch (provider) {
    case 'aws': {
      const client = new SecretsManagerClient({ region: env.AWS_REGION || 'us-east-1' });
      const command = new GetSecretValueCommand({ SecretId: secretId });
      const response = await client.send(command);
      // AWS returns JSON string or plain string
      const secretString = response.SecretString;
      const secretObj = JSON.parse(secretString);
      Object.assign(env, secretObj);
      break;
    }
    case 'gcp': {
      const client = new SecretManagerServiceClient();
      const [version] = await client.accessSecretVersion({
        name: `${secretId}/versions/latest`,
      });
      const payload = version.payload.data.toString('utf8');
      const secretObj = JSON.parse(payload);
      Object.assign(env, secretObj);
      break;
    }
    case 'vault': {
      const vault = Vault({
        endpoint: env.VAULT_ADDR || 'https://vault.mycompany.com',
        token: env.VAULT_TOKEN,
      });
      const secret = await vault.read(secretId); // expects "secret/data/path"
      // For KV v2 the payload is in secret.data.data
      const secretObj = secret.data?.data || secret.data;
      Object.assign(env, secretObj);
      break;
    }
    default:
      throw new Error(`Unsupported SECRET_PROVIDER: ${provider}`);
  }
}

/**
 * Exported configuration object – you can import this everywhere.
 */
module.exports = {
  // ------- static (non‑secret) config -------
  port: env.PORT || 3000,
  nodeEnv: env.NODE_ENV || 'development',

  // ------- secrets (must be present) -------
  get dbUrl() { return getRequired('DATABASE_URL'); },
  get awsAccessKeyId() { return getRequired('AWS_ACCESS_KEY_ID'); },
  get awsSecretAccessKey() { return getRequired('AWS_SECRET_ACCESS_KEY'); },
  get stripeSecretKey() { return getRequired('STRIPE_SECRET_KEY'); },
  // add other getters as you need …

  // ------- helpers -------
  loadSecretFromProvider,
};
```

