### 1.3 Refactor **app.js** – add Helmet, CORS, Rate Limiting, Body‑Parser, Centralised Error Handling

```js
// app.js
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, query, param, validationResult } = require('express-validator');

const app = express();

// -------------------
// 1️⃣ Security middleware
// -------------------
// Hide X‑Powered‑By & set many useful headers
app.use(helmet());

// Enable CORS only for trusted origins (adjust for your environment)
app.use(cors({
  origin: process.env.CORS_ORIGIN?.split(',') || '*', // e.g. "https://myapp.com,https://admin.myapp.com"
  methods: ['GET','POST','PUT','DELETE'],
  credentials: true
}));

// Rate limiting – 100 requests per 15‑min window per IP (adjust as needed)
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Parse JSON bodies (limit size to 10 KB)
app.use(express.json({ limit: '10kb' }));

// -------------------
// 2️⃣ Helper: validation error formatter
// -------------------
function validate(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  next();
}

// -------------------
// 3️⃣ Routes (protected where needed)
// -------------------
// Health check – public
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example: a protected route – only reachable after auth middleware
const { authenticateJwt } = require('./middleware/auth'); // We'll create it later

app.get(
  '/users',
  authenticateJwt,                 // <‑‑ require a valid JWT
  // No user‑supplied params, but we could add pagination validation:
  // query('page').optional().isInt({ min: 1 }),
  // query('limit').optional().isInt({ min: 1, max: 100 }),
  validate,
  (req, res) => {
    // In a real app this would be a DB call – never return raw e‑mail addresses without consent
    const users = [
      { id: 1, name: 'Alice' },   // email removed from public API
      { id: 2, name: 'Bob' }
    ];
    res.json(users);
  }
);

// -------------------
// 4️⃣ Central error handler (hide stack traces from the client)
// -------------------
app.use((err, req, res, next) => {
  console.error(err); // <-- logs to server console / log aggregator
  const status = err.status || 500;
  const response = { message: err.message };

  // Don't leak internal details in production
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }

  res.status(status).json(response);
});

module.exports = app;
```

