## 2. Add Authentication (JWT Example)

### 2.1 Install JWT dependencies  
```bash
npm install jsonwebtoken bcryptjs
```

### 2.2 Create an **auth** middleware (`middleware/auth.js`)

```js
// middleware/auth.js
const jwt = require('jsonwebtoken');

const JWT_SECRET = process.env.JWT_SECRET || 'change-me-in-prod';
const JWT_EXPIRES_IN = process.env.JWT_EXPIRES_IN || '1h';

/**
 * Generate a signed JWT for a given payload (e.g., user id, role).
 * Usage: const token = generateToken({ id: user.id, role: user.role });
 */
function generateToken(payload) {
  return jwt.sign(payload, JWT_SECRET, { expiresIn: JWT_EXPIRES_IN });
}

/**
 * Express middleware – validates the Authorization: Bearer <token> header.
 * On success, attaches `req.user` (the decoded payload) and calls `next()`.
 * On failure, responds with 401 Unauthorized.
 */
function authenticateJwt(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ message: 'Missing or malformed Authorization header' });
  }

  const token = authHeader.slice(7); // strip "Bearer "

  try {
    const payload = jwt.verify(token, JWT_SECRET);
    req.user = payload; // useful downstream (e.g., role‑based checks)
    next();
  } catch (err) {
    return res.status(401).json({ message: 'Invalid or expired token' });
  }
}

module.exports = { generateToken, authenticateJwt };
```

### 2.3 Add a **login** endpoint (demo only – never store plain passwords)

```js
// In app.js, after other imports:
const bcrypt = require('bcryptjs');
const { generateToken } = require('./middleware/auth');

// Mock user store – replace with a real DB
const USERS = [
  { id: 1, username: 'alice', passwordHash: bcrypt.hashSync('alicePwd', 10), role: 'user' },
  { id: 2, username: 'bob',   passwordHash: bcrypt.hashSync('bobPwd',   10), role: 'admin' },
];

app.post(
  '/login',
  // Validate body fields
  body('username').isString().trim(),
  body('password').isString(),
  validate,
  (req, res) => {
    const { username, password } = req.body;
    const user = USERS.find(u => u.username === username);
    if (!user || !bcrypt.compareSync(password, user.passwordHash)) {
      return res.status(401).json({ message: 'Invalid credentials' });
    }
    const token = generateToken({ id: user.id, role: user.role });
    res.json({ token });
  }
);
```

Now the `/users` endpoint is protected: a caller must first POST `/login` to obtain a JWT, then include `Authorization: Bearer <token>` on subsequent requests.

