app.use(express.json({ limit: '10kb' }));

// ---- 2️⃣ Logging -----------------------------------------------------------
app.use(morgan('combined'));                // Apache‑style request logs

// ---- 3️⃣ Rate limiting -----------------------------------------------------
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                // limit each IP to 100 requests per window
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests, please try again later.' },
});
app.use('/api/', apiLimiter); // apply to all API routes (prefix later)

// ---- 4️⃣ Simple JWT auth helper --------------------------------------------
const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing token' });
  }
  const token = authHeader.split(' ')[1];
  try {
    req.user = jwt.verify(token, process.env.JWT_SECRET);
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};

// -------------------------------------------------
// Public routes
// -------------------------------------------------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// -------------------------------------------------
// Protected routes – example of role based access
// -------------------------------------------------
app.get('/api/users', authenticate, (req, res) => {
  // In a real app you’d fetch from a DB, never return raw IDs unless needed.
  // Here we keep static data for demo.
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com'   },
  ];
  // Example: only admin can see the whole list
  if (req.user.role !== 'admin') {
    // Non‑admin gets a limited view (e.g., only their own record)
    const me = users.find(u => u.id === req.user.sub);
    return res.json(me ? [me] : []);
  }
  res.json(users);
});

// -------------------------------------------------
// Example of a safe write endpoint (input validation)
// -------------------------------------------------
app.post(
  '/api/users',
  authenticate,
  // 1️⃣ Validation chain (express‑validator)
  body('name')
    .isString().trim().isLength({ min: 1, max: 50 })
    .withMessage('Name must be a non‑empty string, ≤50 chars'),
  body('email')
    .isEmail().normalizeEmail()
    .withMessage('A valid email is required'),

  // 2️⃣ Middleware that aborts on validation errors
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }
    next();
  },

  // 3️⃣ Business logic – placeholder (use parameterised queries!)
  (req, res) => {
    const { name, email } = req.body;
    // INSERT INTO users (name,email) VALUES ($1,$2)  <-- use pg/knex/etc.
