## 3. Concrete Refactor (Minimal but Secure)

Below is a **drop‑in replacement** for `app.js` that addresses the above points while staying easy to understand. You can copy‑paste it into the same file; the only dependencies you need to add are listed after the code.

```js
// app.js – Secure starter template
// ------------------------------------------------
// 1️⃣  Load environment / configuration
// 2️⃣  Harden HTTP headers and CORS
// 3️⃣  Add rate limiting and logging
// 4️⃣  Provide a JWT‑based auth middleware (can be swapped for sessions)
// 5️⃣  Centralised error handling
// ------------------------------------------------

require('dotenv').config();                 // <-- .env file for PORT, JWT_SECRET, etc.
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { body, param, query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');

const app = express();

// ---------- Middleware ----------
app.use(helmet());                      // Secure HTTP headers (CSP, HSTS, etc.)
app.use(cors({                           // Liberal CORS for demo – tighten in prod
  origin: process.env.CORS_ORIGIN || '*',
}));
app.use(express.json());               // Parse JSON bodies
app.use(morgan('combined'));           // Request logging (combined Apache format)

// ---------- Rate Limiting ----------
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100,                // limit each IP to 100 requests per window
  message: { error: 'Too many requests, please try again later.' },
});
app.use('/users', apiLimiter); // apply only to endpoints that may be sensitive

// ---------- Authentication ----------
/**
 * Simple JWT verification middleware.
 * In a real world app you would also handle token revocation,
 * refresh tokens, etc.
 */
function authenticateJwt(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or malformed Authorization header' });
  }
  const token = authHeader.split(' ')[1];
  try {
    const payload = jwt.verify(token, process.env.JWT_SECRET);
    // Attach user info to request for downstream use
    req.user = payload;
    next();
  } catch (err) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
}

// ---------- Routes ----------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

/**
 * Example protected route.
 * Only authenticated callers can see the users list.
 * Input validation is shown for query parameters (if any future filters are added).
 */
app.get(
  '/users',
  authenticateJwt,
  // Example of future validation (e.g., ?limit=10)
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  (req, res, next) => {
    // Validate request parameters
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // In a production system you would fetch from a DB and filter using
    // parameterised queries. Here we keep the static example.
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];
    res.json(users);
  }
);

// ---------- Centralised Error Handler ----------
app.use((err, req, res, next) => {
  // Log the error (could be winston, pino, etc.)
  console.error(err);
  // Do NOT expose stack traces to clients in production
  const status = err.status || 500;
  const response = { error: err.message || 'Internal Server Error' };
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }
  res.status(status).json(response);
});

// ---------- Server Start ----------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

module.exports = app; // Export for integration tests
```

### 3.1. New Dependencies

Add the following packages (run once):

```bash
npm install helmet cors express-rate-limit morgan express-validator dotenv jsonwebtoken
```

> **Why each is required**
> - **helmet** – sets secure HTTP headers (CSP, HSTS, X‑Content‑Type‑Options, etc.).
> - **cors** – defines who may call your API.
> - **express-rate-limit** – mitigates brute‑force and DoS attempts.
> - **morgan** – logs every request; you can pipe it to a file or a logging service.
> - **express-validator** – centralised input validation/sanitisation.
> - **dotenv** – keeps secrets (JWT secret, port, DB credentials) out of source control.
> - **jsonwebtoken** – common, well‑tested JWT implementation.

