## 🛠️ Concrete Code Improvements

Below is a **refactored `app.js`** that addresses the most critical findings while staying easy to read. Feel free to cherry‑pick pieces that suit your current deployment stage.

```js
// app.js
/**
 * Secure Express application – demo version.
 * Implements:
 *   • Helmet (security headers)
 *   • Rate limiting
 *   • Basic JWT authentication for protected routes
 *   • Global error handling (no stack traces in prod)
 *   • Structured request logging (morgan + winston)
 *   • HTTPS enforcement when behind a proxy
 */

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const winston = require('winston');
const jwt = require('jsonwebtoken'); // npm i jsonwebtoken
require('dotenv').config(); // npm i dotenv

const app = express();

// --------------------------------------------------
// 1️⃣  Middleware stack
// --------------------------------------------------
app.use(helmet());                         // A04 – security headers
app.use(express.json());                   // future body parsing
app.set('trust proxy', 1);                 // needed for secure cookie / IP detection behind proxies

// ---- Logging -------------------------------------------------
const logger = winston.createLogger({
  level: process.env.NODE_ENV === 'production' ? 'info' : 'debug',
  format: winston.format.json(),
  transports: [new winston.transports.Console()],
});
app.use(morgan('combined', { stream: { write: msg => logger.info(msg.trim()) } }));

// ---- Rate limiting -------------------------------------------
const limiter = rateLimit({
  windowMs: 60 * 1000, // 1 minute
  max: 100,            // limit each IP to 100 requests/min
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ---- HTTPS enforcement (if behind a TLS‑terminating proxy) ----
if (process.env.ENFORCE_HTTPS === 'true') {
  app.use((req, res, next) => {
    if (req.secure) {
      next();
    } else {
      // Redirect HTTP → HTTPS
      res.redirect(`https://${req.headers.host}${req.originalUrl}`);
    }
  });
}

// --------------------------------------------------
// 2️⃣  Authentication helper (JWT)
// --------------------------------------------------
const JWT_SECRET = process.env.JWT_SECRET || 'CHANGE_ME_IN_PROD';

// Simple middleware that checks for a valid Bearer token.
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];
  if (!token) return res.sendStatus(401); // Unauthorized

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) return res.sendStatus(403); // Forbidden (invalid token)
    req.user = user;
    next();
  });
}

// --------------------------------------------------
// 3️⃣  Routes
// --------------------------------------------------

// Public health endpoint – can stay unauthenticated
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example login endpoint – issues a JWT (normally you would verify credentials)
app.post('/login', (req, res) => {
  // In a real app, validate username/password against DB, hash passwords, etc.
  const { username } = req.body;
  if (!username) return res.status(400).json({ error: 'username required' });

  const user = { name: username }; // payload can contain id/role etc.
  const token = jwt.sign(user, JWT_SECRET, { expiresIn: '1h' });
  res.json({ token });
});

/* -------------------------------------------------
   Protected resource – now requires a valid JWT.
   Additionally, we **redact** personal email addresses
   before sending them out (A01 – data exposure).
--------------------------------------------------- */
const ALL_USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

app.get('/users', authenticateToken, (req, res) => {
  // Optionally filter fields based on role/claims (`req.user.role`)
  const safeUsers = ALL_USERS.map(u => ({
    id: u.id,
    name: u.name,
    // Hide email unless the token contains a claim that permits it
    email: req.user?.role === 'admin' ? u.email : undefined,
  }));
  res.json(safeUsers);
});

// --------------------------------------------------
// 4️⃣  Global error handler (no stack traces in prod)
// --------------------------------------------------
app.use((err, _req, res, _next) => {
  logger.error(err);
  const status = err.status || 500;
  const response = {
    message: status === 500 ? 'Internal Server Error' : err.message,
  };
  // In development, you may want to include err.stack
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }
  res.status(status).json(response);
});

// --------------------------------------------------
// 5️⃣  Server start (port from env, default 3000)
// --------------------------------------------------
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT}`);
});

module.exports = app;
```

