## 📦  Sample implementation that works for **all three** situations  

```js
// config.js – central place to load secrets
require('dotenv').config();               // Loads .env if it exists (dev only)

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// ------------------------------------------------------------------
// 1️⃣  Helper that prefers process.env, falls back to AWS Secrets Manager
// ------------------------------------------------------------------
async function getSecret(name) {
  // a) If the secret is already in the environment (K8s, ECS, etc.) use it.
  if (process.env[name]) {
    return process.env[name];
  }

  // b) Otherwise try AWS Secrets Manager (you can switch to GCP/Azure analogues).
  const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });
  const command = new GetSecretValueCommand({ SecretId: name });

  try {
    const response = await client.send(command);
    // Secrets may be stored as plain string or JSON‑encoded.
    if (response.SecretString) {
      // If the secret is a JSON object we return the whole object.
      try { return JSON.parse(response.SecretString); } 
      catch (_) { return response.SecretString; }
    }
    // If binary secret (unlikely for keys) you could decode it here.
    return null;
  } catch (err) {
    console.error(`Unable to load secret "${name}":`, err);
    return null;
  }
}

// ------------------------------------------------------------------
// 2️⃣  Export an object with all the secrets the app needs.
// ------------------------------------------------------------------
module.exports = {
  // Example: a DB connection string
  DATABASE_URL: process.env.DATABASE_URL || (await getSecret('prod/database/url')),

  // AWS SDK credentials (if you really need to pass them – usually the SDK reads them from IAM role)
  AWS_ACCESS_KEY_ID: process.env.AWS_ACCESS_KEY_ID || (await getSecret('prod/aws/accessKeyId')),
  AWS_SECRET_ACCESS_KEY: process.env.AWS_SECRET_ACCESS_KEY || (await getSecret('prod/aws/secretAccessKey')),

  // Third‑party API keys
  ANTHROPIC_API_KEY: process.env.ANTHROPIC_API_KEY || (await getSecret('prod/anthropic/apiKey')),
  STRIPE_SECRET_KEY: process.env.STRIPE_SECRET_KEY || (await getSecret('prod/stripe/secretKey')),
  LOGFIRE_TOKEN: process.env.LOGFIRE_TOKEN || (await getSecret('prod/logfire/token')),

  // Add any future secrets here…
};
```

#### How to use it in the app

```js
// app.js (or any module that needs a secret)
const { DATABASE_URL, STRIPE_SECRET_KEY } = require('./config');

// Example – initialize a DB client with the secret:
const { Pool } = require('pg');
const db = new Pool({ connectionString: DATABASE_URL });

// Example – Stripe SDK:
const stripe = require('stripe')(STRIPE_SECRET_KEY);
```

**Key points of the pattern**

| ✅ | Detail |
|---|--------|
| **Source‑order precedence** – environment → cloud secret → error (instead of silently falling back to a hard‑coded value). |
| **Single source of truth** – all secrets are accessed through `config.js`, making audit & rotation simple. |
| **No secret files in the repo** – the only `.env` you keep locally is a *development* aid and is git‑ignored. |
| **Graceful fallback for CI** – CI pipelines can set environment variables directly; the same code works unchanged in production. |

