// app.js – Refactored secret handling
const express = require('express');
const AWS = require('aws-sdk');
const app = express();

// Configure the SDK (region, credentials via IAM role or instance profile)
AWS.config.update({ region: 'us-east-1' });
const secretsManager = new AWS.SecretsManager();

// Helper to retrieve a secret once and cache it
const secretCache = {};
async function getSecret(name) {
  if (secretCache[name]) return secretCache[name];

  const data = await secretsManager
    .getSecretValue({ SecretId: name })
    .promise();

  // Secrets Manager returns either SecretString or SecretBinary
