## Recommended Approach – Move From `.env` Files to a Real Secrets Store  

Below are **concrete patterns** you can adopt now, tailored to three common deployment environments. All of them continue to let developers use a local `.env` file for *local* development, but *production* reads secrets from a dedicated manager.

### 1️⃣ Centralised “Secret Loader” Wrapper  

Create a tiny module, e.g. `config/secretLoader.js`, that abstracts where the values come from:

```js
// config/secretLoader.js
const logger = require('../logger');               // your pino instance
const { promisify } = require('util');

async function loadSecrets() {
  // 1️⃣ Local development – load .env if it exists
  if (process.env.NODE_ENV !== 'production') {
    try {
      // .env is deliberately *not* .env.test
      require('dotenv').config({ path: '.env' });
      logger.info('Loaded .env file for local development');
    } catch (e) {
      logger.warn('No .env file found – proceeding with existing env vars');
    }
  }

  // 2️⃣ Production – pull from a secrets manager (example: AWS Secrets Manager)
  if (process.env.NODE_ENV === 'production') {
    const AWS = require('aws-sdk');
    const secretsManager = new AWS.SecretsManager({ region: process.env.AWS_REGION });

    // The secret name could be passed via an env var or baked in CI
    const secretName = process.env.AWS_SECRETS_NAME;
    if (!secretName) {
      throw new Error('AWS_SECRETS_NAME environment variable is required in production');
    }

    const getSecretValue = promisify(secretsManager.getSecretValue.bind(secretsManager));
    const data = await getSecretValue({ SecretId: secretName });

    // Secrets manager returns a JSON string by default
    const secretJson = data.SecretString ? JSON.parse(data.SecretString) : {};

    // Inject each secret into process.env (only if not already set)
    Object.entries(secretJson).forEach(([k, v]) => {
      if (!process.env[k]) process.env[k] = v;
    });

    logger.info(`Loaded ${Object.keys(secretJson).length} secrets from AWS Secrets Manager`);
  }
}

module.exports = { loadSecrets };
```

**How to use it in `app.js`**

```js
// app.js (top)
const { loadSecrets } = require('./config/secretLoader');

(async () => {
  try {
    await loadSecrets();          // ← pulls from .env (dev) or AWS Secrets Manager (prod)
    // Then you can safely read process.env.* anywhere below
    const app = require('./server'); // your Express bootstrap (or keep everything in this file)
    // start the server as usual …
  } catch (err) {
    console.error('Failed to load secrets:', err);
    process.exit(1);
  }
})();
```

