const helmet = require('helmet');                 // A5 – Security Misconfiguration
const cors = require('cors');                     // A5 – Secure CORS
const rateLimit = require('express-rate-limit'); // A10 – Logging/Monitoring (throttling)
const morgan = require('morgan');                 // A10 – Logging
const { body, query, param, validationResult } = require('express-validator'); // A1/A7 – Input validation
require('dotenv').config();                       // Configuration via env variables

const app = express();

// ---------- 1. Basic hardening ----------
app.use(helmet());                                 // Sets CSP, HSTS, X‑Frame‑Options, etc.
app.disable('x-powered-by');                       // Hide framework fingerprint

// ---------- 2. CORS ----------
app.use(
  cors({
    origin: process.env.CORS_ORIGIN || 'https://my‑trusted‑domain.com',
    methods: ['GET', 'POST', 'OPTIONS'],
    allowedHeaders: ['Content-Type', 'Authorization'],
  })
);

// ---------- 3. Body parsing (if you need POST/PUT later) ----------
