);

// Example of a POST endpoint that demonstrates input validation & sanitisation (A1/A7)
app.post(
  '/api/comments',
  // Validation chain
  [
    body('postId').isInt({ gt: 0 }).withMessage('postId must be a positive integer'),
    body('author')
      .trim()
      .isLength({ min: 2, max: 50 })
      .withMessage('author must be 2‑50 chars'),
    body('comment')
      .trim()
      .isLength({ min: 1, max: 500 })
      .withMessage('comment must be 1‑500 chars')
      .escape(), // basic XSS sanitisation
  ],
  asyncHandler(async (req, res) => {
    // Retrieve validation results
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // At this point the data is known to be safe – store in DB, etc.
    const { postId, author, comment } = req.body;
    // … insert logic …
