## Detailed Recommendations & Sample Code

### 1. Harden the Express app with security middleware
```js
// --- security‑middleware.js -------------------------------------------------
const helmet = require('helmet');
const cors   = require('cors');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize'); // example for NoSQL injection
const xssClean = require('xss-clean'); // protect against reflected XSS

module.exports = function (app) {
  // Secure HTTP headers
  app.use(helmet());

  // CORS – restrict to known origins (adjust as needed)
  app.use(cors({
    origin: process.env.CORS_ORIGIN || 'https://my‑trusted‑frontend.example.com',
    methods: ['GET','POST','PUT','DELETE'],
    credentials: true,
  }));

  // Basic rate limiting (adjust limits for your traffic)
  const apiLimiter = rateLimit({
    windowMs: 15 * 60 * 1000,   // 15 minutes
    max: 100,                    // limit each IP to 100 requests per window
    message: { error: 'Too many requests, please try again later.' }
  });
  app.use('/api/', apiLimiter); // only protect API routes

  // Data sanitisation
  app.use(mongoSanitize()); // removes $ and . from req.body/req.query
  app.use(xssClean());      // strips XSS vectors from user input
};
```

