### 2. Add Authentication (JWT example)

```js
// --- auth.js ---------------------------------------------------------------
const jwt = require('jsonwebtoken');

// Middleware to protect routes
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer <token>

  if (!token) return res.status(401).json({ error: 'Missing token' });

  jwt.verify(token, process.env.JWT_SECRET, (err, user) => {
    if (err) return res.status(403).json({ error: 'Invalid token' });
    req.user = user;           // attach payload to request
    next();
  });
}

// Helper to issue a token (e.g., after login)
function issueToken(payload) {
  // Short expiry for API tokens; refresh token flow can be added later
  return jwt.sign(payload, process.env.JWT_SECRET, { expiresIn: '1h' });
}

module.exports = { authenticateToken, issueToken };
```

**Protect the `/users` endpoint**
