## Recommendations – Proper Secret Management

Even though the sample app doesn’t currently need secrets, any production‑ready extension (database connections, third‑party APIs, JWT signing, etc.) will inevitably require confidential values. Below are best‑practice patterns and concrete code snippets you can adopt now so that adding secrets later is safe and consistent.

### 1. Load **only** non‑secret configuration from a `.env` file (development only)

```js
// config.js
if (process.env.NODE_ENV !== 'production') {
  // Load .env *only* in non‑production environments
  // This avoids accidentally shipping a .env file to production.
  require('dotenv').config({ path: '.env' });
}

module.exports = {
  // Example non‑secret values
  port: process.env.PORT || 3000,
  // Example secret placeholders (will be overridden in prod)
  jwtSecret: process.env.JWT_SECRET,
  dbUrl: process.env.DATABASE_URL,
  // Add other config keys here
};
```

**Why this matters**

* `dotenv` is *explicitly* disabled when `NODE_ENV=production`, preventing accidental reliance on a file that might be checked into source control.
* All configuration is centralized so you can replace the source later (e.g., swap `.env` for a secrets‑manager call) without touching the rest of the code.

### 2. Pull secrets from a **managed secrets service** in production

Below are three common cloud‑provider examples. Pick the one that matches your deployment environment and replace the placeholder code in `config.js`.

#### a) AWS Secrets Manager (Node SDK v3)

```js
// config.js (production path)
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

async function loadAwsSecret(secretName) {
  const client = new SecretsManagerClient({ region: process.env.AWS_REGION });
  const command = new GetSecretValueCommand({ SecretId: secretName });
  const { SecretString } = await client.send(command);
  return JSON.parse(SecretString);
}

// Export a promise that resolves when secrets are loaded
module.exports = (async () => {
  const secret = await loadAwsSecret(process.env.AWS_SECRET_NAME);
  return {
    port: process.env.PORT || 3000,
    jwtSecret: secret.JWT_SECRET,
    dbUrl: secret.DATABASE_URL,
    // …more keys
  };
})();
```

#### b) Google Cloud Secret Manager

```js
// config.js (production)
const { SecretManagerServiceClient } = require('@google-cloud/secret-manager');

async function getGcpSecret(name) {
  const client = new SecretManagerServiceClient();
  const [version] = await client.accessSecretVersion({ name });
  return version.payload.data.toString('utf8');
}

module.exports = (async () => {
  const jwtSecret = await getGcpSecret(process.env.GCP_JWT_SECRET_NAME);
  const dbUrl    = await getGcpSecret(process.env.GCP_DB_URL_SECRET_NAME);
  return {
    port: process.env.PORT || 3000,
    jwtSecret,
    dbUrl,
  };
})();
```

#### c) Azure Key Vault

```js
// config.js (production)
const { SecretClient } = require('@azure/keyvault-secrets');
const { DefaultAzureCredential } = require('@azure/identity');

async function getAzureSecret(vaultUrl, secretName) {
  const credential = new DefaultAzureCredential();
  const client = new SecretClient(vaultUrl, credential);
  const secret = await client.getSecret(secretName);
  return secret.value;
}

module.exports = (async () => {
  const vaultUrl = process.env.AZURE_KEY_VAULT_URL;
  const jwtSecret = await getAzureSecret(vaultUrl, 'JwtSecret');
  const dbUrl    = await getAzureSecret(vaultUrl, 'DatabaseUrl');
  return {
    port: process.env.PORT || 3000,
    jwtSecret,
    dbUrl,
  };
})();
```

