## 3️⃣ Concrete Refactor for `app.js`

Below is a **minimal, production‑ready starter** that:

1. **Never reads a `.env` file in production** (it only loads it when `NODE_ENV !== 'production'`).
2. **Pulls secrets from AWS Secrets Manager** (you can swap the block for GCP/Azure/Vault).
3. **Keeps the rest of the hardening middleware** I previously suggested.

```js
// app.js – hardened + secret‑manager example (AWS)
require('dotenv').config({ // only used for local dev
  path: process.env.NODE_ENV === 'production' ? undefined : '.env.development',
});

const express   = require('express');
const helmet    = require('helmet');
const cors      = require('cors');
const rateLimit = require('express-rate-limit');
const morgan    = require('morgan');
const jwt       = require('jsonwebtoken');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const app = express();

// ---------- 1️⃣ Load secrets from AWS Secrets Manager (async) ----------
async function loadSecrets() {
  if (process.env.NODE_ENV !== 'production') return; // skip in dev, we already have .env

  const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });
  const command = new GetSecretValueCommand({ SecretId: 'myApp/prod/secrets' });

  try {
    const { SecretString } = await client.send(command);
    const secrets = JSON.parse(SecretString);
    // Populate process.env so the rest of the code can use them transparently
    Object.assign(process.env, secrets);
  } catch (e) {
    console.error('❌ Failed to retrieve secrets from AWS Secrets Manager:', e);
    process.exit(1); // abort start‑up – you don't want to run without credentials
  }
}

// Immediately invoke before the server starts
loadSecrets().then(() => startServer()).catch(console.error);

// ---------- 2️⃣ Global security middleware ----------
function applyMiddleware() {
  app.use(helmet());
  app.use(cors({ origin: process.env.ALLOWED_ORIGIN || '*' }));
  app.use(express.json());
  app.use(morgan('combined'));
  app.disable('x-powered-by');

  const limiter = rateLimit({
    windowMs: 15 * 60 * 1000,
    max: 100,
    standardHeaders: true,
    legacyHeaders: false,
  });
  app.use(limiter);
}
applyMiddleware();

// ---------- 3️⃣ JWT helper ----------
const JWT_SECRET = process.env.JWT_SECRET ?? 'CHANGE_ME_IN_SECRETS';
function authenticateToken(req, res, next) {
  const auth = req.headers.authorization;
  const token = auth && auth.split(' ')[1];
  if (!token) return res.sendStatus(401);
  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) return res.sendStatus(403);
    req.user = user;
    next();
  });
}

// ---------- 4️⃣ Routes ----------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', authenticateToken, (req, res) => {
  // Future: fetch from DB using the DATABASE_URL secret
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob',   email: 'bob@example.com' },
  ]);
});

// ---------- 5️⃣ Error handling ----------
app.use((err, _req, res, _next) => {
  console.error(err);
  res.status(500).json({ error: 'Internal Server Error' });
});

// ---------- 6️⃣ Server start ----------
function startServer() {
  const PORT = process.env.PORT ?? 3000;
  app.listen(PORT, () => console.log(`🚀 Server listening on ${PORT}`));
}

module.exports = app;
```

**Key points in the snippet**

- **`loadSecrets()`** runs *before* any route logic, ensuring `process.env` contains the real secrets only when the process is in `production`.
- If the secret fetch fails, the app **exits** rather than continuing with empty credentials.
- The code **still supports a local `.env.development`** for developer convenience. No `.env` file is read in production.
- All other security middleware (Helmet, CORS, rate limiter, logging) is kept intact.

